@layer components {
  .ew-text-field {
    /* anatomy: root, label, control, description, error, ornament-before, indicator */
  }
  .ew-text-field {
    display: grid;
    gap: 6px;
    font-family: var(--ew-font-body, system-ui, sans-serif);
  }
  .ew-text-field__label { color: var(--ew-color-fg-default, inherit); font-size: 14px; font-weight: 600; }
  .ew-text-field__control {
    padding: var(--ew-field-padding-y, 8px) var(--ew-field-padding-x, 12px);
    border: var(--ew-structure-field-border-width, 1px) var(--ew-structure-field-border-style, solid) var(--ew-color-field-border, #888);
    border-radius: var(--ew-structure-field-radius, var(--ew-radius-md, 8px));
    background: var(--ew-color-field-bg, #fff);
    color: var(--ew-color-fg-default, inherit);
    font: inherit;
    box-shadow: var(--ew-structure-field-shadow, none);
  }
  .ew-text-field[data-variant="filled"] .ew-text-field__control {
    background: color-mix(in oklch, var(--ew-color-bg-surface) 80%, var(--ew-color-fg-default));
    border-color: transparent;
  }
  .ew-text-field[data-variant="underline"] .ew-text-field__control,
  .ew-text-field:where([data-underline="true"]) .ew-text-field__control {
    border-radius: 0;
    border-width: 0 0 var(--ew-structure-field-border-width, 2px) 0;
    background: transparent;
  }
  .ew-text-field__control:focus-visible { outline: 2px solid var(--ew-color-field-focus, Highlight); outline-offset: 1px; }
  .ew-text-field__description, .ew-text-field__error { font-size: 14px; color: var(--ew-color-fg-muted, #666); }
  .ew-text-field[data-invalid="true"] .ew-text-field__error, .ew-text-field__error { color: var(--ew-color-danger-bg, #a33); }
  .ew-text-field[data-size="sm"] .ew-text-field__control { padding: 6px 8px; font-size: 14px; }
  .ew-text-field[data-size="lg"] .ew-text-field__control { padding: 12px 14px; font-size: 16px; }
  /* spec variant variant=outline */
  .ew-text-field[data-variant="outline"] { --ew-spec-variant-variant: outline; }
  /* spec variant variant=filled */
  .ew-text-field[data-variant="filled"] { --ew-spec-variant-variant: filled; }
  /* spec variant variant=underline */
  .ew-text-field[data-variant="underline"] { --ew-spec-variant-variant: underline; }
  .ew-text-field:not([data-variant]) { --ew-spec-variant-variant: outline; }
  .ew-text-field[data-size="sm"] { --ew-spec-size: sm; }
  .ew-text-field[data-size="md"] { --ew-spec-size: md; }
  .ew-text-field[data-size="lg"] { --ew-spec-size: lg; }
  .ew-text-field:not([data-size]) { --ew-spec-size: md; }
  @media (prefers-reduced-motion: reduce) {
    .ew-text-field, .ew-text-field *, .ew-text-field *::before, .ew-text-field *::after {
      transition: none !important;
      animation: none !important;
    }
  }
}
